import { validate } from '@mintlify/common';
import { mkdir, rm, writeFile } from 'fs/promises';
import { join } from 'path';
import { CMD_EXEC_PATH, NEXT_PROPS_PATH } from '../constants.js';
import listener from '../local-preview/listener/index.js';
import { notifyPackageInputChange } from '../local-preview/packages/index.js';
import * as logs from '../logging-state.js';
const watcher = vi.hoisted(() => ({
    handlers: {},
}));
vi.mock('../constants.js', async (importOriginal) => {
    const actual = await importOriginal();
    const { mkdtempSync } = await import('fs');
    const { tmpdir } = await import('os');
    const { join } = await import('path');
    const root = mkdtempSync(join(tmpdir(), 'listener-manifest-'));
    return {
        ...actual,
        CMD_EXEC_PATH: join(root, 'docs'),
        CLIENT_PATH: join(root, 'client'),
        CONTENT_PATH: join(root, 'client'),
        NEXT_PROPS_PATH: join(root, 'client', 'src', '_props'),
        NEXT_PUBLIC_PATH: join(root, 'client', 'public'),
    };
});
vi.mock('chokidar', () => {
    const watch = () => {
        const instance = {
            on: (event, handler) => {
                watcher.handlers[event] = handler;
                return instance;
            },
            close: async () => { },
        };
        return instance;
    };
    return { default: { watch }, watch };
});
vi.mock('@mintlify/common', async (importOriginal) => {
    const actual = await importOriginal();
    return { ...actual, validate: vi.fn().mockRejectedValue(new Error('not an OpenAPI spec')) };
});
vi.mock('@mintlify/prebuild', async (importOriginal) => {
    const actual = await importOriginal();
    return {
        ...actual,
        getMintIgnore: vi.fn().mockResolvedValue([]),
        discoverOverlayFiles: vi.fn().mockResolvedValue([]),
    };
});
vi.mock('../local-preview/packages/index.js', () => ({
    notifyPackageInputChange: vi.fn(),
    writePackageBuildProps: vi.fn(),
}));
const addChangeLogSpy = vi.spyOn(logs, 'addChangeLog');
const triggerRefresh = vi.fn();
const change = async (filename) => {
    listener(triggerRefresh, {});
    await vi.waitFor(() => expect(watcher.handlers.change).toBeDefined());
    await watcher.handlers.change?.(filename);
};
const edited = (filename) => expect(addChangeLogSpy).toHaveBeenCalledWith(expect.objectContaining({ props: expect.objectContaining({ filename }) }));
const manifest = { name: 'docs', dependencies: { recharts: '2.15.0' } };
beforeAll(async () => {
    await mkdir(join(CMD_EXEC_PATH, 'snippets'), { recursive: true });
    await mkdir(NEXT_PROPS_PATH, { recursive: true });
    await writeFile(join(CMD_EXEC_PATH, 'package.json'), JSON.stringify(manifest));
    await writeFile(join(CMD_EXEC_PATH, 'snippets', 'package.json'), JSON.stringify(manifest));
    await writeFile(join(NEXT_PROPS_PATH, 'customLanguages.json'), '[]');
});
afterAll(async () => {
    await rm(join(CMD_EXEC_PATH, '..'), { recursive: true, force: true });
});
beforeEach(() => {
    vi.clearAllMocks();
    watcher.handlers = {};
});
describe('listener package manifest changes', () => {
    it('leaves a root package.json to the packages runtime', async () => {
        await change('package.json');
        expect(notifyPackageInputChange).toHaveBeenCalledWith('package.json', 'potentialJsonOpenApiSpec');
        expect(validate).not.toHaveBeenCalled();
        expect(triggerRefresh).not.toHaveBeenCalled();
        edited('package.json');
    });
    it('still parses a nested package.json', async () => {
        await change(join('snippets', 'package.json'));
        expect(validate).toHaveBeenCalledWith(manifest);
        expect(triggerRefresh).toHaveBeenCalledOnce();
    });
});
